// DocAccessImpact Who gets, loses, raises or lowers the access (diffAccess); shown before saving.
type DocAccessImpact struct {
	Down []DocImpactPerson `json:"down"`
	Gain []DocImpactPerson `json:"gain"`
	Lose []DocImpactPerson `json:"lose"`
	Up   []DocImpactPerson `json:"up"`
}

// DocAck Acknowledgement (docAck): version, time and device are stored. «Ознакомление без кадрового значения» (DOC-04).
type DocAck struct {
	Device *string `json:"device,omitempty"`
}

// DocAckResult Result of ackDocument.
type DocAckResult struct {
	Acked bool `json:"acked"`

	// At UTC RFC3339 instant. Write requests must use the Z suffix; retain the IANA timezone separately for local calendars.
	//
	// Examples: 2026-10-05T06:00:00Z
	At      Instant `json:"at"`
	Version int64   `json:"version"`
}

// DocActivity Audit entry of a document.
type DocActivity struct {
	Action string `json:"action"`

	// At UTC RFC3339 instant. Write requests must use the Z suffix; retain the IANA timezone separately for local calendars.
	//
	// Examples: 2026-10-05T06:00:00Z
	At Instant `json:"at"`

	// By Member of the organization shown by name.
	By      DocMemberRef `json:"by"`
	Details string       `json:"details"`

	// Id Examples: 10000000-0000-4000-8000-000000000001
	Id Id `json:"id"`
}

// DocActivityList Audit of a document.
type DocActivityList struct {
	Items      []DocActivity `json:"items"`
	NextCursor *string       `json:"nextCursor"`
}

